/**
 * Bake-time OpenTelemetry providers. Installed before `agent.ts` so a
 * module-scope meter, tracer, or logger binds to a real provider.
 * `instrumentation.ts` is not loaded.
 */
import { installCustomerOtel } from "../otel/customer.js";
import { displayPath } from "./context.js";
import { findModuleFile } from "./fs.js";
const instrumentedAgentDirs = new Set();
export function agentDirHasInstrumentation(agentDir) {
    return instrumentedAgentDirs.has(agentDir);
}
export function resetInstrumentationRegistryForTests() {
    instrumentedAgentDirs.clear();
}
const INSTRUMENTATION_FILE = "instrumentation.ts is not loaded. Delete this file. See https://cursor.com/docs/bdk/guides/opentelemetry#migrating-from-serve-otel.";
export async function loadInstrumentation(ctx, agentDir) {
    installCustomerOtel();
    instrumentedAgentDirs.add(agentDir);
    const path = await findModuleFile(agentDir, "instrumentation");
    if (path !== undefined) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, path),
            message: INSTRUMENTATION_FILE,
        });
    }
    return true;
}
